const out = {};
for (const l of L) out[l] = {};
for (const [key, vals] of Object.entries(T)) {
  const [ns, k] = key.split('.');
  L.forEach((l, i) => {
    out[l][ns] ??= {};
    out[l][ns][k] = vals[i];
  });
}
fs.mkdirSync('messages', { recursive: true });
for (const l of L) fs.writeFileSync(`messages/${l}.json`, JSON.stringify(out[l], null, 2) + '\n');
console.log('keys:', Object.keys(T).length, '| locales:', L.length);
